package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.time.YearMonth; import java.time.ZoneOffset; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class FinanceStatisticsService{private final LedgerRepository ledgers;private final FinanceTransactionRepository transactions;public FinanceStatisticsService(LedgerRepository l,FinanceTransactionRepository t){ledgers=l;transactions=t;}public Mono<MonthlyStatisticsView> month(UUID a,UUID id,YearMonth m){return own(a,id).flatMap(ledger->{Instant from=m.atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC),to=m.plusMonths(1).atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC);return transactions.findAllByLedgerIdAndOwnerIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(id,a,from,to).collectList().map(xs->{BigDecimal in=BigDecimal.ZERO,out=BigDecimal.ZERO,tr=BigDecimal.ZERO;for(FinanceTransactionEntity tx:xs){if(tx.type()==TransactionType.INCOME)in=in.add(tx.amount());else if(tx.type()==TransactionType.EXPENSE)out=out.add(tx.amount());else if(tx.type()==TransactionType.TRANSFER)tr=tr.add(tx.amount());}return new MonthlyStatisticsView(m,in,out,tr,xs.size());});});}public Flux<TransactionView> search(UUID a,UUID id,String q){return own(a,id).flatMapMany(ledger->transactions.findAllByLedgerIdAndOwnerIdOrderByOccurredAtDesc(id,a).filter(t->(t.payee()!=null&&t.payee().toLowerCase().contains(q.toLowerCase()))||(t.note()!=null&&t.note().toLowerCase().contains(q.toLowerCase()))).map(t->new TransactionView(t.id(),t.ledgerId(),t.type(),t.accountId(),t.targetAccountId(),t.amount(),t.currency(),t.categoryId(),t.payee(),t.note(),t.occurredAt(),t.status(),t.source())));}private Mono<LedgerEntity> own(UUID a,UUID id){return ledgers.findById(id).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}}
